const embeddingData = $input.first().json;
const extractData = $('Extract Embedding').first().json;

// Format vector for PostgreSQL (should be like: [0.1,0.2,0.3,...])
let vectorString = '';
if (extractData.embedding && Array.isArray(extractData.embedding)) {
  vectorString = '[' + extractData.embedding.join(',') + ']';
} else {
  throw new Error('Embedding is not an array: ' + typeof extractData.embedding);
}

return [{
  json: {
    id: extractData.id,
    userInput: extractData.userInput,
    aiResponse: extractData.aiResponse,
    feedback: extractData.feedback,
    embedding: extractData.embedding,
    vectorString: vectorString
  }
}];

const inputData = $input.first().json;
const extractData = $('Extract Embedding').first().json;

const exampleText = `User: ${extractData.userInput} | Assistant: ${extractData.aiResponse}`;
const isLike = extractData.feedback === 1 || extractData.feedback === 'like';

return [{
  json: {
    content: extractData.userInput,
    embedding: extractData.embedding,
    examples: isLike ? [exampleText] : [],
    negative: !isLike ? [exampleText] : [],
    success: isLike ? 1 : 0,
    response: extractData.aiResponse
  }
}];

const data = $input.first().json;
const current = data.rag || {};
const inputData = data.input;

let usage = current.usage_count || 0;
let success = current.success_rate || 0;

usage += 1;

let examples = current.examples || [];
let negative = current.negative_examples || [];

const exampleText = `User: ${inputData.userInput} | Assistant: ${inputData.aiResponse}`;

if (inputData.feedback === 1 || inputData.feedback === 'like') {
  // Remove from negative if exists
  negative = negative.filter(ex => ex !== exampleText);

  // Add to examples if not exists
  if (!examples.includes(exampleText)) {
    examples.push(exampleText);
  }
  success = ((success * (usage - 1)) + 1) / usage;
} else {
  // Remove from examples if exists
  examples = examples.filter(ex => ex !== exampleText);

  // Add to negative if not exists
  if (!negative.includes(exampleText)) {
    negative.push(exampleText);
  }
  success = ((success * (usage - 1)) + 0) / usage;
}

// Limit array size
const MAX_EXAMPLES = 500;
if (examples.length > MAX_EXAMPLES) examples = examples.slice(0, MAX_EXAMPLES);
if (negative.length > MAX_EXAMPLES) negative = negative.slice(0, MAX_EXAMPLES);

return [{
  json: {
    id: current.id,
    usage: usage,
    success: success,
    examples: examples,
    negative: negative
  }
}];

